import {guides,parts,partById,categories,kits} from './catalog.js';
import {matchProject,normalizeInventory,searchText} from './solver.js';

const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>typeof u==='string'&&/^https:\/\//i.test(u)?esc(u):'#';
const state={inventory:{},demo:false,category:'all',query:'',sort:'default',ready:false,archiveType:'projects',archiveQuery:'',page:0,data:{},modal:null,inventoryQuery:''};
const modal=$('#modal');
let toastTimer;
try{const saved=JSON.parse(localStorage.getItem('arc.inventory.v1')||'{}');state.inventory=normalizeInventory(saved.inventory);state.demo=!!saved.demo;}catch{}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function save(){try{localStorage.setItem('arc.inventory.v1',JSON.stringify({inventory:state.inventory,demo:state.demo}));}catch{notify('Запас изменён, но браузер не разрешает сохранение. Выгрузи JSON.');}updateCount();renderProjects();}
function totalInventory(){return Object.values(state.inventory).reduce((a,b)=>a+b,0);}
function updateCount(){$('#inventory-count').textContent=totalInventory();}
function setQuantity(id,quantity){const next=Math.min(999,Math.max(0,Math.floor(Number(quantity)||0)));if(next)state.inventory[id]=next;else delete state.inventory[id];state.demo=false;save();}
function nameOf(id){return partById[id]?.name || id.replace(/^(cmp|comp|part):/,'').replaceAll('_',' ');}
function art(type){
 const shapes={
 camera:'<path d="M50 59h27l10-15h45l11 15h32v72H50z"/><path d="M50 79h33m57 0h35M63 67h9m80 0h10"/><circle cx="112" cy="97" r="30"/><circle cx="112" cy="97" r="21"/><circle cx="112" cy="97" r="10"/><path d="m96 82 28 28m-61 31v10h28m58-10v10h-20"/>',
 monitor:'<rect x="42" y="46" width="145" height="87" rx="3"/><path d="M48 53h133v67H48zM98 134v15h33v-15M86 151h57M57 110l22-24 19 12 27-29 21 24 17-14"/><circle cx="160" cy="69" r="7"/><path d="M29 59v26h-9m174 10h17V77m-70-44h29"/>',
 alarm:'<rect x="57" y="34" width="55" height="114" rx="4"/><rect x="128" y="50" width="23" height="86" rx="4"/><circle cx="84" cy="57" r="5"/><path d="M70 86h28m-28 9h28m-28 9h28m-28 9h28m-28 9h28M164 64q30 26 0 52m10-63q40 37 0 74M48 34H31v17m17 97H31v-17"/>',
 plant:'<path d="M116 102h57l-9 46h-39zM144 102V62m0 19q-33 0-30-26 30 0 30 26zm0-8q29 0 30-25-28 0-30 25zM49 60h39v80H49zM49 76h39M57 55h23M58 107q39-43 63 2"/><path stroke-dasharray="3 4" d="M58 113q39-43 63 2"/><path d="M37 149h148"/>',
 pump:'<path d="M35 71h49v68H35zM42 64h35M35 91h49M49 121h22M84 120h23v-12h40V87h34v45h-34v-12h-27v16H84"/><circle cx="163" cy="110" r="11"/><path d="M165 87V49h32v36m-5 8q-7 12 0 12t0-12M45 49h24m77 93h36M133 60h-21V43h-13"/>',
 light:'<rect x="39" y="94" width="56" height="43" rx="5"/><path d="M50 106h15m-15 8h24M95 115h24V77h16m0-24h37l10 34h-57zM154 87v51m-18 0h37M156 37V25m-27 17-8-9m59 10 10-10m1 42h14M110 75H98"/><path stroke-dasharray="3 3" d="M134 95l-14 46m51-46 15 46"/>',
 fan:'<circle cx="117" cy="78" r="48"/><circle cx="117" cy="78" r="39"/><circle cx="117" cy="78" r="8"/><path d="M117 70q-35-40-38 0l30 9m14-8q47-18 27 17l-25-5m-9 3q-6 45-31 15l26-19M108 126v22m18-22v22M88 150h58M56 112v27h25"/>',
 server:'<rect x="74" y="32" width="86" height="35" rx="3"/><rect x="74" y="76" width="86" height="35" rx="3"/><path d="M86 44h37m-37 10h29m-29 34h37m-37 11h29M116 111v22m-53 0h108M63 133v12m108-12v12"/><circle cx="143" cy="49" r="4"/><circle cx="143" cy="93" r="4"/><path d="M44 48q-17 14 0 27m-8-34q-25 23 0 42M183 48q17 14 0 27"/>'
 };
 return `<svg class="drawing" viewBox="0 0 230 180" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">${shapes[type]||shapes.server}</g><g stroke="currentColor" opacity=".3" stroke-width=".7"><path d="M20 20h15m-15 0v15m190-15h-15m15 0v15M20 160h15m-15 0v-15m190 15h-15m15 0v-15"/><path stroke-dasharray="2 4" d="M18 157h195"/></g></svg>`;
}
function renderProjects(){
 let list=guides.filter(p=>(state.category==='all'||p.category===state.category)&&searchText(p,state.query)&&(!state.ready||matchProject(p,state.inventory).complete));
 if(state.sort==='match')list.sort((a,b)=>matchProject(b,state.inventory).score-matchProject(a,state.inventory).score);
 $('#results-count').textContent=`${list.length} / ${guides.length} сборок`;
 $('#project-grid').innerHTML=list.length?list.map(p=>{const m=matchProject(p,state.inventory);return `<article class="project-card"><button class="project-open" data-project="${p.id}" aria-label="Открыть: ${esc(p.name)}"><div class="card-art"><span class="card-index">ARC / ${p.code}</span>${art(p.icon)}<span class="card-tag">${esc(p.level.toUpperCase())}</span></div><div class="card-body"><div class="card-meta"><span>${esc(categories[p.category].toUpperCase())}</span><span>${p.time}</span></div><h3>${p.name}</h3><p>${p.summary}</p><div class="card-bottom"><span class="${m.complete?'match-good':''}">${m.complete?'✓ КОМПЛЕКТ СОБРАН':m.have?`${m.have} ИЗ ${m.total} ДЕТАЛЕЙ`:`${m.total} ПОЗИЦИИ В КОМПЛЕКТЕ`}</span><b>↗</b></div><div class="progress-line"><span style="width:${m.score}%"></span></div></div></button></article>`;}).join(''):`<div class="empty"><strong>Пока нет совпадений.</strong><p>${state.ready?'Добавь детали в «Мой запас» или отключи фильтр полного комплекта.':'Попробуй другое слово или категорию.'}</p><button class="small-button" data-action="reset-filters">Сбросить фильтры</button></div>`;
}
function showModal(title,content){state.modal=title;modal.setAttribute('aria-label',title);$('#modal-content').innerHTML=`<div class="modal-head"><span>${esc(title)}</span><button class="close" data-action="close" aria-label="Закрыть">×</button></div><div class="modal-inner">${content}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){modal.close();state.modal=null;if(location.hash.startsWith('#build='))history.replaceState(null,'','#projects');}
modal.addEventListener('cancel',()=>{state.modal=null;if(location.hash.startsWith('#build='))history.replaceState(null,'','#projects');});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function sourceLinks(sources){return sources.length?`<div class="source-links">${sources.map(([n,u])=>`<a href="${safeURL(u)}" target="_blank" rel="noopener">${esc(n)} ↗</a>`).join('')}</div>`:'<p class="part-note">Проверь паспорта своих конкретных модулей.</p>';}
function openGuide(id){const p=guides.find(p=>p.id===id);if(!p)return;const m=matchProject(p,state.inventory);history.replaceState(null,'',`#build=${encodeURIComponent(id)}`);
 showModal(`ARC / МАРШРУТ ${p.code}`,`<span class="section-code">${categories[p.category].toUpperCase()}</span><h2 class="modal-title">${p.name}</h2><p class="modal-lead">${p.summary}</p><div class="detail-meta"><span>${p.time} · оценка</span><span>${p.level}</span><span>${m.have} / ${m.total} позиций есть</span>${state.demo?'<span>Пример инвентаря</span>':''}</div><div class="notice">${p.note}</div><div class="flow">${p.flow.map((s,i)=>`${i?'<b>→</b>':''}<span>${esc(s)}</span>`).join('')}</div><div class="detail-layout"><div><h3>Что понадобится</h3><div>${m.rows.map(r=>`<div class="bom-row"><button class="bom-name" data-part="${r.id}">${esc(nameOf(r.id))} ↗</button><small class="${r.missing?'':'good'}">${r.have}/${r.quantity}</small>${r.missing?`<button class="small-button" data-have="${r.id}" data-guide="${p.id}" data-quantity="${r.quantity}">Есть +</button>`:'<span class="good">✓</span>'}</div>`).join('')}</div><p class="part-note">Нажми на деталь: требования, возможный донор и проверка.</p></div><aside><h3>Инструменты и условия</h3><ul class="tools-list">${p.tools.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Источники</h3>${sourceLinks(p.sources)}</aside></div><h3>Порядок сборки</h3>${p.steps.map(([title,text],i)=>`<div class="step"><span>0${i+1}</span><div><h4>${title}</h4><p>${esc(text)}</p></div></div>`).join('')}<h3>Проверка результата</h3><p class="plan-checks">${p.check}</p><div class="modal-actions"><button class="button primary" data-download="${p.id}">Скачать план <span>↓</span></button><button class="button secondary" data-shopping="${p.id}">Список недостающего <span>↓</span></button>${p.firmware?`<a class="button secondary" href="${p.firmware}" download>Скетч Arduino ↓</a>`:''}</div>`);
}
function showInventory(){state.inventoryQuery='';showModal('ARC / МОЙ ЗАПАС',`<span class="section-code">ТВОИ РЕСУРСЫ</span><h2 class="modal-title">Начнём с того, что есть.</h2><p class="modal-lead">Добавляй исправные детали после проверки маркировки. Количество влияет на подбор. Запас сохраняется только в этом браузере.</p><div class="inventory-summary"><span id="inventory-summary-label"></span><button class="small-button" data-action="discover">Подобрать сборки ↗</button></div><label class="sr-only" for="inventory-search">Поиск деталей</label><input id="inventory-search" class="inventory-search" type="search" placeholder="Деталь, устройство или донор…"><div id="inventory-rows"></div><div class="modal-actions"><button class="button primary" data-action="discover">Показать мои возможности <span>↗</span></button></div><div class="inline-tools" style="margin-top:24px"><button data-action="export-inventory">Выгрузить запас JSON</button><button data-action="import-inventory">Загрузить запас JSON</button><button data-action="clear-inventory">Очистить запас</button></div><input id="inventory-file" type="file" accept="application/json,.json" hidden><p class="dataset-note">Импорт объединяет запасы по большему количеству каждой детали. Сборки оцениваются отдельно: общий запас не резервируется одновременно для всех проектов.</p>`);renderInventory();$('#inventory-search').addEventListener('input',e=>{state.inventoryQuery=e.target.value;renderInventory();});$('#inventory-file').addEventListener('change',importInventory);}
function renderInventory(){const known=new Set(parts.map(p=>p.id));const extra=Object.keys(state.inventory).filter(id=>!known.has(id)).map(id=>({id,name:nameOf(id),spec:'Позиция из исходного корпуса. Совместимость не проверена.',donor:''}));const list=[...parts,...extra].filter(p=>searchText(p,state.inventoryQuery));$('#inventory-summary-label').innerHTML=`<strong>${totalInventory()}</strong> единиц · ${Object.keys(state.inventory).length} позиций${state.demo?' · типовой пример':''}`;
 $('#inventory-rows').innerHTML=list.length?list.map(p=>`<div class="inventory-row"><div><h4>${esc(p.name)}</h4><p>${esc(p.spec)}</p></div><div class="quantity"><button data-delta="-1" data-id="${esc(p.id)}" aria-label="Убрать одну: ${esc(p.name)}">−</button><input type="number" min="0" max="999" value="${state.inventory[p.id]||0}" data-quantity-id="${esc(p.id)}" aria-label="Количество: ${esc(p.name)}"><button data-delta="1" data-id="${esc(p.id)}" aria-label="Добавить одну: ${esc(p.name)}">+</button></div></div>`).join(''):'<div class="empty"><p>Такой позиции в стартовом наборе нет. Детали из корпуса можно добавлять через карточки архива.</p><button class="small-button" data-action="archive-components">Открыть компоненты</button></div>';
}
async function loadData(kind){if(state.data[kind])return state.data[kind];const response=await fetch(`data/${kind}.json`);if(!response.ok)throw new Error(`Не удалось загрузить данные (${response.status})`);const json=await response.json();state.data[kind]=json;return json;}
async function openPart(id){state.partId=id;const p=partById[id];const title=nameOf(id);showModal('ARC / КАРТОЧКА ДЕТАЛИ',`<span class="section-code">ДЕТАЛЬ И ЕЁ ВОЗМОЖНОСТИ</span><h2 class="modal-title">${esc(title)}</h2><p class="modal-lead">${esc(p?.spec||'Компонент из машинно извлечённого корпуса. Проверь точный тип, параметры и совместимость.')}</p><h3>Где искать</h3><p class="modal-lead">${esc(p?.donor||'Ищем точное совпадение идентификатора в разборах устройств…')}</p><div id="part-donors"></div>${p?`<h3>Перед использованием</h3><div class="notice">${esc(p.check)}</div>`:''}<h3>Если дома не нашлось</h3><p class="plan-checks">Мастерская ремонта, местное сообщество обмена, объявления о ненужной технике, магазин электронных компонентов. Уточняй модель и работоспособность; наличие и цены здесь не проверяются.</p><div class="modal-actions"><button class="button primary" data-part-add="${esc(id)}">Добавить в запас <span>+</span></button><button class="button secondary" data-action="inventory">Мой запас</button></div><p class="dataset-note">Возможный донор — подсказка для поиска. Наличие детали внутри устройства не подтверждает её исправность.</p>`);
 if(!p){try{const devices=await loadData('devices');if(state.modal!=='ARC / КАРТОЧКА ДЕТАЛИ'||state.partId!==id||!$('#part-donors'))return;const matches=devices.filter(d=>d.parts.some(x=>x.id===id));$('#part-donors').innerHTML=matches.length?matches.slice(0,12).map(d=>`<div class="archive-donor">${esc(d.name)} <span class="badge">требует проверки</span></div>`).join(''):'<div class="notice">Точного совпадения в 1 115 разборах нет. Автоматическая замена по похожему названию не применяется.</div>';}catch{const target=$('#part-donors');if(target)target.innerHTML='<p class="error">Не удалось загрузить разборы. Проверь подключение и повтори.</p>';}}
}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function downloadGuide(id,shopping=false){const p=guides.find(p=>p.id===id);if(!p)return;const m=matchProject(p,state.inventory);let text=`ARC — ${p.name}\n${shopping?'НЕДОСТАЮЩИЕ ДЕТАЛИ':'ПЛАН СБОРКИ'}\n\n${p.note}\n${state.demo?'Инвентарь: типовой пример.\n':''}\n`;
 const rows=shopping?m.missing:m.rows;text+=rows.length?rows.map(r=>`${r.missing?'[ ]':'[x]'} ${nameOf(r.id)} — нужно ${r.quantity}, есть ${r.have}, не хватает ${r.missing}\nТребования: ${partById[r.id].spec}\nГде искать: ${partById[r.id].donor}\nПроверка: ${partById[r.id].check}`).join('\n\n'):'Недостающих позиций нет. Проверь совместимость и исправность.';
 if(!shopping)text+=`\n\nИНСТРУМЕНТЫ\n${p.tools.join('\n')}\n\nШАГИ\n${p.steps.map(([t,s],i)=>`${i+1}. ${t}\n${s}`).join('\n\n')}\n\nПРОВЕРКА\n${p.check}`;
 text+=`\n\nИСТОЧНИКИ\n${p.sources.map(([n,u])=>`${n}\n${u}`).join('\n')}\n\nhttps://github.com/hermandoronin/arc-computer\n`;
 download(`ARC-${p.id.split(':')[1]}-${shopping?'parts':'plan'}.txt`,text);notify(shopping?'Список недостающего выгружен.':'План сборки выгружен.');}
async function importInventory(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Файл слишком большой. Максимум 2 МБ.');const json=JSON.parse(await file.text());if(json.version!==1||!json.inventory||Array.isArray(json.inventory))throw new Error('Нужен файл запаса ARC версии 1.');const incoming=normalizeInventory(json.inventory);for(const [id,count]of Object.entries(incoming))state.inventory[id]=Math.max(state.inventory[id]||0,count);state.demo=false;save();renderInventory();notify(`Импортировано ${Object.keys(incoming).length} позиций.`);}catch(error){notify(error.message||'Не удалось прочитать JSON.');}e.target.value='';}
async function openArchive(type='projects'){state.archiveType=type;state.archiveQuery='';state.page=0;
 showModal('ARC / АРХИВ ЗНАНИЙ',`<span class="section-code">ВОССТАНОВЛЕННЫЙ КОРПУС / 2026</span><h2 class="modal-title">Много идей. Точные источники.</h2><p class="modal-lead">Ищи проекты, устройства-доноры и компоненты. Это исходные машинные извлечения: характеристики и связи требуют сверки.</p><div class="archive-tabs" id="archive-tabs">${[['projects','Проекты · 1 225'],['devices','Устройства · 1 115'],['components','Компоненты · 55 414']].map(([k,n])=>`<button data-archive-type="${k}" class="${type===k?'active':''}">${n}</button>`).join('')}</div><label class="sr-only" for="archive-search">Поиск по архиву</label><div class="archive-search-row"><input class="archive-search" id="archive-search" type="search" placeholder="Название или деталь: camera, Arduino, полив…"><button class="small-button" data-action="archive-match">По моему запасу</button></div><div class="archive-results-meta" id="archive-meta" aria-live="polite">Загрузка…</div><div id="archive-results"></div><div id="archive-pagination"></div>`);
 $('#archive-search').addEventListener('input',e=>{state.archiveQuery=e.target.value;state.page=0;renderArchive();});await renderArchive();}
async function renderArchive(){const type=state.archiveType;const target=$('#archive-results');if(!target)return;$('#archive-meta').textContent='Загрузка…';try{let data=await loadData(type);if(state.modal!=='ARC / АРХИВ ЗНАНИЙ'||type!==state.archiveType)return;data=data.filter(d=>searchText(d,state.archiveQuery));if(type==='projects'&&state.archiveMatch)data.sort((a,b)=>matchProject(b,state.inventory).score-matchProject(a,state.inventory).score);const pages=Math.max(1,Math.ceil(data.length/30));state.page=Math.min(state.page,pages-1);const page=data.slice(state.page*30,state.page*30+30);$('#archive-meta').textContent=`Найдено ${data.length.toLocaleString('ru-RU')} · страница ${state.page+1} / ${pages}${type==='projects'&&state.archiveMatch?' · по совпадению запаса':''}`;
 $('#archive-results').innerHTML=page.length?page.map(d=>{const m=type==='projects'?matchProject(d,state.inventory):null;return `<article class="archive-row"><div><h4>${esc(d.name)}</h4><p>${esc((d.summary||d.specifications||d.category||'').slice(0,190))}${(d.summary||'').length>190?'…':''}</p><span class="archive-id">${esc(d.id)}${m?` · ${m.have}/${m.total} единиц в запасе`:''}</span></div><button class="small-button" data-record="${esc(type==='devices'?d.origin:d.id)}" data-kind="${type}">Открыть ↗</button></article>`;}).join(''):'<div class="empty"><strong>Ничего не найдено.</strong><p>Попробуй название на английском или идентификатор детали.</p></div>';
 $('#archive-pagination').innerHTML=`<button class="small-button" data-page="-1" ${state.page===0?'disabled':''}>← Назад</button><span>${state.page+1} / ${pages}</span><button class="small-button" data-page="1" ${state.page>=pages-1?'disabled':''}>Дальше →</button>`;$('#archive-pagination').className='archive-pagination';}catch(error){if($('#archive-meta'))$('#archive-meta').textContent='Не удалось загрузить архив.';if($('#archive-results'))$('#archive-results').innerHTML='<div class="empty"><p>Проверь подключение. Для офлайн-поиска сначала сохрани сайт целиком.</p><button class="small-button" data-action="retry-archive">Повторить загрузку</button></div>';}}
function openRecord(kind,id){const d=state.data[kind]?.find(d=>(kind==='devices'?d.origin:d.id)===id);if(!d)return;const isProject=kind==='projects',isDevice=kind==='devices';let body=`<span class="badge">Исходная запись · не проверено</span><h2 class="modal-title">${esc(d.name)}</h2><p class="archive-id">${esc(d.id)}</p><p class="modal-lead">${esc(d.summary||d.specifications||d.category||'')}</p>`;
 if(isProject){body+=`<div class="notice">Публикация восстановлена по сырому архиву. Этот состав извлечён автоматически и может быть неполным. Полный комплект не означает готовую или безопасную сборку.</div>${d.source?sourceLinks([[`Исходная публикация${d.author?' · '+d.author:''}`,d.source]]):''}<h3>Извлечённый состав</h3>${d.bom.map(r=>`<div class="bom-row"><button class="bom-name" data-part="${esc(r.id)}">${esc(nameOf(r.id))} ↗</button><small>× ${esc(r.quantity)}</small><button class="small-button" data-raw-add="${esc(r.id)}">Есть +</button></div><p class="dataset-note">${esc(r.notes)}</p>`).join('')}`;}
 else if(isDevice){body+=`<div class="notice">Состав зависит от конкретной модели и ревизии. Разборка и электрическая безопасность не проверены.${d.hazards?.length?' Метки исходника: '+esc(d.hazards.join(', '))+'.':''}</div><h3>Потенциальные детали внутри</h3>${d.parts.length?d.parts.map(r=>`<div class="bom-row"><button class="bom-name" data-part="${esc(r.id)}">${esc(nameOf(r.id))} ↗</button><small>× ${esc(r.quantity)}</small><button class="small-button" data-raw-add="${esc(r.id)}">Есть +</button></div>`).join(''):'<p class="part-note">Компоненты в этой записи не выделены.</p>'}<p class="dataset-note">«Есть +» добавляет одну уже извлечённую и проверенную тобой деталь, а не устройство целиком.</p>`;}
 else {body+=`<div class="notice">Это каталожная запись, а не подтверждение наличия. Совпадение по названию не гарантирует совместимость с проектом.</div><h3>Происхождение</h3><p class="dataset-note">${esc(typeof d.provenance==='object'?JSON.stringify(d.provenance):d.provenance)}</p><button class="button primary" data-raw-add="${esc(id)}">Добавить одну в запас <span>+</span></button>`;}
 body+=`<div class="modal-actions"><button class="button secondary" data-back-archive="${kind}">← Вернуться в архив</button><button class="button secondary" data-action="inventory">Мой запас</button></div>`;showModal('ARC / ИСХОДНАЯ ЗАПИСЬ',body);}
function about(){showModal('ARC / О ПРОЕКТЕ',`<span class="section-code">OPEN SOURCE / FIELD EDITION 0.1</span><h2 class="modal-title">Знания, которые остаются с тобой.</h2><p class="modal-lead">ARC помогает связать доступные детали, устройства-доноры и полезные проекты. Эта версия использует восстановленный корпус проекта hermandoronin/arc-computer.</p><div class="modal-stat"><div><strong>1 225</strong><span>проектов из извлечений</span></div><div><strong>1 115</strong><span>записей устройств</span></div><div><strong>55 414</strong><span>компонентов в пакете</span></div></div><h3>Что работает в MVP</h3><p class="plan-checks">Инвентарь с количеством, детерминированный подбор восьми стартовых сборок, поиск по всему импортированному каталогу, точные связи деталей с донорами, экспорт планов и запаса, сохранение для офлайна. Локальная история не передаётся на сервер.</p><h3>Границы данных</h3><p class="plan-checks">У 1 225 проектов восстановлены адреса исходных публикаций из сохранённого сырого корпуса. Это не проверка содержания источников. Автоматические инструкции не показываются как готовые руководства; аппаратные сборки не проходили стендовые испытания. Каталожные comp: и извлечённые cmp: — разные пространства идентификаторов, автоматического приравнивания нет.</p><h3>Авторство и лицензии</h3><p class="plan-checks">Код ARC — Apache-2.0. Для базы репозиторий указывает CC-BY-4.0 с учётом лицензий первоисточников. Ссылки и авторы сохранены там, где они есть; условия конкретной публикации нужно учитывать отдельно. Изображение мастерской — созданная ImageGen иллюстрация, не фотография работающего прототипа.</p>${sourceLinks([['Исходный проект и условия использования','https://github.com/hermandoronin/arc-computer']])}<p class="dataset-note">Контрольная сумма восстановленного пакета SHA-256:<br>0fae7546690cab3cb06bd36471c592fab81ff20dd844bdb467f42ecf8d224fb6</p>`);}
const coreFiles=['./','index.html','style.css','app.js','solver.js','catalog.js','assets/workbench.webp','assets/mono.woff2','assets/display.woff2','assets/favicon.svg','assets/door-alarm.ino'];
let swReady=null;
if('serviceWorker' in navigator)swReady=navigator.serviceWorker.register('sw.js').then(()=>navigator.serviceWorker.ready).catch(()=>null);
async function saveOffline(){const button=$('#offline-button');button.disabled=true;$('#offline-status').textContent='Загрузка каталога и изображений…';try{if(!swReady||!await swReady)throw new Error('Сервис офлайна недоступен в этом браузере.');const cache=await caches.open('arc-field-v1');await cache.addAll([...coreFiles,'data/projects.json','data/devices.json','data/components.json','data/manifest.json']);$('#offline-status').textContent='Сохранено. Открой сайт один раз перед уходом из сети. Внешние источники требуют интернета.';button.textContent='✓ Сайт сохранён для офлайна';notify('Сайт и полный каталог доступны без сети в этом браузере.');}catch(error){$('#offline-status').textContent=error.message||'Не удалось сохранить: проверь сеть и свободное место.';}finally{button.disabled=false;}}

document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;
 if(d.project)return openGuide(d.project);
 if(d.part)return openPart(d.part);
 if(d.donor)return openPart('part:'+d.donor);
 if(d.kit!==undefined){const kit=kits[Number(d.kit)];for(const id of kit.ids)state.inventory['part:'+id]=Math.max(1,state.inventory['part:'+id]||0);state.demo=true;state.sort='match';$('#sort').value='match';save();notify('Типовой набор добавлен. Уточни реальные детали в «Мой запас».');$('#projects').scrollIntoView({behavior:'smooth'});return;}
 if(d.filter){state.category=d.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===d.filter);x.setAttribute('aria-pressed',String(x.dataset.filter===d.filter));});return renderProjects();}
 if(d.delta){setQuantity(d.id,(state.inventory[d.id]||0)+Number(d.delta));return renderInventory();}
 if(d.have){setQuantity(d.have,Number(d.quantity));openGuide(d.guide);notify('Деталь добавлена в запас.');return;}
 if(d.partAdd||d.rawAdd){const id=d.partAdd||d.rawAdd;setQuantity(id,(state.inventory[id]||0)+1);return notify(`Добавлено: ${nameOf(id)}`);}
 if(d.download)return downloadGuide(d.download);
 if(d.shopping)return downloadGuide(d.shopping,true);
 if(d.archiveType){state.archiveType=d.archiveType;state.page=0;document.querySelectorAll('[data-archive-type]').forEach(x=>x.classList.toggle('active',x.dataset.archiveType===d.archiveType));return renderArchive();}
 if(d.page){state.page+=Number(d.page);await renderArchive();$('#archive-results')?.scrollIntoView({block:'start'});return;}
 if(d.record)return openRecord(d.kind,d.record);
 if(d.backArchive)return openArchive(d.backArchive);
 switch(d.action){
  case 'close':return closeModal();case 'inventory':return showInventory();case 'archive':return openArchive();case 'archive-devices':return openArchive('devices');case 'archive-components':return openArchive('components');case 'retry-archive':return renderArchive();case 'about':return about();case 'offline':return saveOffline();
  case 'archive-match':state.archiveMatch=!state.archiveMatch;state.archiveType='projects';state.page=0;document.querySelectorAll('[data-archive-type]').forEach(x=>x.classList.toggle('active',x.dataset.archiveType==='projects'));b.textContent=state.archiveMatch?'По порядку':'По моему запасу';return renderArchive();
  case 'discover':state.sort='match';state.ready=false;state.query='';state.category='all';$('#sort').value='match';$('#ready-only').checked=false;$('#project-search').value='';document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='all');x.setAttribute('aria-pressed',String(x.dataset.filter==='all'));});renderProjects();closeModal();$('#projects').scrollIntoView({behavior:'smooth'});return;
  case 'reset-filters':state.category='all';state.query='';state.ready=false;$('#project-search').value='';$('#ready-only').checked=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='all');x.setAttribute('aria-pressed',String(x.dataset.filter==='all'));});return renderProjects();
  case 'export-inventory':return download('ARC-inventory.json',JSON.stringify({version:1,inventory:state.inventory},null,2),'application/json');
  case 'import-inventory':return $('#inventory-file').click();
  case 'clear-inventory':state.inventory={};state.demo=false;save();renderInventory();return notify('Запас очищен.');
 }
});
document.addEventListener('change',e=>{if(e.target.dataset.quantityId){setQuantity(e.target.dataset.quantityId,e.target.value);renderInventory();}});
$('#project-search').addEventListener('input',e=>{state.query=e.target.value;renderProjects();});
$('#ready-only').addEventListener('change',e=>{state.ready=e.target.checked;renderProjects();});
$('#sort').addEventListener('change',e=>{state.sort=e.target.value;renderProjects();});
$('#categories').innerHTML=Object.entries(categories).map(([id,name])=>`<button class="filter ${id==='all'?'active':''}" data-filter="${id}" aria-pressed="${id==='all'}">${name}</button>`).join('');
$('#kit-options').innerHTML=kits.map((k,i)=>`<button class="kit-button" data-kit="${i}"><span class="kit-symbol">${['⌁','⊞','↟'][i]}</span><span>${k.name}</span></button>`).join('');
document.querySelectorAll('[data-art]').forEach(el=>el.innerHTML=art(el.dataset.art));
updateCount();renderProjects();
function route(){if(location.hash.startsWith('#build=')){try{openGuide(decodeURIComponent(location.hash.slice(7)));}catch{}}}
window.addEventListener('hashchange',route);route();
window.addEventListener('offline',()=>{ $('#offline-status').textContent='Сеть недоступна. Ранее сохранённые данные доступны в этом браузере.';});
